INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist "spezifisch" ein Kriterium des SMART-Prinzips?', 2, '[{"text": "Ja", "correct": true, "because": "Erstes Kriterium von SMART"}, {"text": "Nein", "correct": false, "because": "Es ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt "spezifisch" im SMART-Prinzip?', 3, '[{"text": "Klar und eindeutig formuliert", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Vage und allgemein", "correct": false, "because": "Widerspricht Spezifität"}, {"text": "Ohne Zielvorgabe", "correct": false, "because": "Spezifität braucht Details"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Spezifische Ziele sind klar definiert. b) Spezifität ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Spezifität ist Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente machen ein Ziel spezifisch?', 4, '[{"text": "Genaue Beschreibung", "correct": true, "because": "Definiert das Ziel"}, {"text": "Unklare Formulierung", "correct": false, "because": "Widerspricht Spezifität"}, {"text": "Konkrete Ergebnisse", "correct": true, "because": "Macht Ziel greifbar"}, {"text": "Allgemeine Aussagen", "correct": false, "because": "Fehlt Präzision"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ziel ohne Spezifität SMART sein?', 2, '[{"text": "Nein", "correct": true, "because": "Spezifität ist essenziell"}, {"text": "Ja", "correct": false, "because": "Widerspricht SMART"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel ist nicht spezifisch?', 3, '[{"text": "Irgendwann besser werden", "correct": true, "because": "Zu vage"}, {"text": "Server bis 15. März installieren", "correct": false, "because": "Klar definiert"}, {"text": "App mit 3 Funktionen entwickeln", "correct": false, "because": "Spezifisch genug"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Spezifität nur für große Projekte wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Ziele relevant"}, {"text": "Ja", "correct": false, "because": "Auch kleine Ziele brauchen Klarheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich aus spezifischen Zielen?', 3, '[{"text": "Klarheit für alle Beteiligten", "correct": true, "because": "Vermeidet Verwirrung"}, {"text": "Maximale Flexibilität", "correct": false, "because": "Spezifität setzt Grenzen"}, {"text": "Keine Planung nötig", "correct": false, "because": "Fördert Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Spezifität erhöht die Umsetzbarkeit. b) Spezifische Ziele sind immer langfristig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Was fehlt bei "Projekt abschließen"?', 2, '[{"text": "Spezifität", "correct": true, "because": "Zu allgemein"}, {"text": "Teamzuweisung", "correct": false, "because": "Nicht Teil von SMART"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein spezifisches Ziel mehrere Aspekte umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "Wenn klar definiert"}, {"text": "Nein", "correct": false, "because": "Flexibilität ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel ist spezifisch?', 3, '[{"text": "Datenbank mit 5 Tabellen erstellen", "correct": true, "because": "Klar und präzise"}, {"text": "Irgendwas programmieren", "correct": false, "because": "Zu vage"}, {"text": "Team motivieren", "correct": false, "because": "Nicht konkret"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Spezifität dasselbe wie Messbarkeit?', 2, '[{"text": "Nein", "correct": true, "because": "Spezifisch ist klar, messbar ist quantifizierbar"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Kriterien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fragen fördern Spezifität?', 4, '[{"text": "Was soll erreicht werden?", "correct": true, "because": "Definiert Ziel"}, {"text": "Wie viel kostet es?", "correct": false, "because": "Nicht Teil von Spezifität"}, {"text": "Wer macht es?", "correct": true, "because": "Klarheit über Verantwortung"}, {"text": "Warum ist es egal?", "correct": false, "because": "Widerspricht Zielsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen spezifische Ziele immer schriftlich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit reicht aus"}, {"text": "Ja", "correct": false, "because": "Form ist flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel ist unspezifisch?', 3, '[{"text": "Software verbessern", "correct": true, "because": "Fehlt Detail"}, {"text": "Backup täglich um 18 Uhr", "correct": false, "because": "Klar definiert"}, {"text": "Test mit 10 Szenarien", "correct": false, "because": "Spezifisch genug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Spezifität ohne Zeitangabe bestehen?', 2, '[{"text": "Ja", "correct": true, "because": "Zeit ist separates Kriterium"}, {"text": "Nein", "correct": false, "because": "Unabhängig von Terminiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Spezifität im SMART-Prinzip?', 3, '[{"text": "Gibt klare Richtung", "correct": true, "because": "Fokussiert Ziel"}, {"text": "Erhöht Kosten", "correct": false, "because": "Unabhängig davon"}, {"text": "Macht Ziele vage", "correct": false, "because": "Gegenteil von Spezifität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Spezifität vermeidet Missverständnisse. b) Spezifische Ziele sind immer lang.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Ziel der Spezifität im SMART-Prinzip?', 3, '[{"text": "Präzise Zielvorgabe", "correct": true, "because": "Fördert Klarheit"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Spezifität"}, {"text": "Keine Planung", "correct": false, "because": "Fördert Struktur"}]');
